import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.util.concurrent.atomic.AtomicInteger;

public class CommentTest {

    @Test
    public void newNodeNameIsCommentTest() {
        Comment comment = new Comment("data");
        assertEquals("comment", comment.nodeName());
    }

    @Test
    public void noDataReturnsEmptyStringTest() {
        Comment comment = new Comment("");
        assertEquals("", comment.getData());
    }

    @Test
    public void withDataReturnsCorrectDataTest() {
        String data = "Hello, World!";
        Comment comment = new Comment(data);
        assertEquals(data, comment.getData());
    }

    @Test
    public void setDataUpdatesContentTest() {
        Comment comment = new Comment("data");
        comment.setData("newData");
        assertEquals("newData", comment.getData());
    }

    @Test
    public void outerHtmlHeadAddsCommentToHTMLTest() {
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        Appendable accum = outContent;
        AtomicInteger count = new AtomicInteger(0);
        Document.OutputSettings settings = new Document.OutputSettings();

        Comment comment = new Comment("data");
        comment.outerHtmlHead(accum, 1, settings);

        assertEquals(count.get(), 1);
    }

    @Test
    public void outerHtmlTailAddsCommentToHTMLTest() {
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        Appendable accum = outContent;
        AtomicInteger count = new AtomicInteger(0);
        Document.OutputSettings settings = new Document.OutputSettings();

        Comment comment = new Comment("data");
        comment.outerHtmlTail(accum, 1, settings);

        assertEquals(count.get(), 1);
    }

    @Test
    public void toStringIncludesNodeNameAndDataTest() {
        Comment comment = new Comment("data");
        String expectedOutput = "<comment>data</comment>";
        assertEquals(expectedOutput, comment.toString());
    }

    @Test
    public void cloneCreatesNewCommentWithSameDataTest() {
        Comment comment1 = new Comment("data");
        Comment comment2 = comment1.clone();
        assertEquals(comment1.getData(), comment2.getData());
    }

    @Test
    public void isXmlDeclarationReturnsFalseForNonDeclarationCommentsTest() {
        Comment comment = new Comment("data");
        assertFalse(comment.isXmlDeclaration());
    }

    @Test
    public void asXmlDeclarationReturnsNullForNonDeclarationCommentsTest() {
        Comment comment = new Comment("data");
        assertNull(comment.asXmlDeclaration());
    }

    @Test
    public void asXmlDeclarationReturnsCorrectlyParsedDeclarationTest() throws IOException {
        String xmlDeclaration = "<!DOCTYPE html>";
        Document document = Document.parse(xmlDeclaration);
        Element declarationElement = document.body().firstChild();
        assertTrue(declarationElement.toString(), declarationElement.toString()).contains("<!DOCTYPE html>");
        Comment comment = new Comment(xmlDeclaration);
        assertEquals(declarationElement, comment.asXmlDeclaration());
    }

}
